{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C14","C15","C03","C04","C11","C17","C10","C38","C66","C56","C65"],
  "contradictory_card_ids": ["C29","C42"],
  "prediction_basis_card_ids": ["C14","C15","C03","C04","C11","C17","C66"],
  "claims": [
    {
      "claim": "The query contains the same saligenin beta2-agonist head group as salbutamol; salbutamol absolute oral bioavailability in fasting subjects was 7.2% and 11.4%, both below the 20% threshold.",
      "card_ids": ["C14","C15"]
    },
    {
      "claim": "Bambuterol, a related beta2-agonist, has human oral bioavailability of about 10% of the administered dose, below the 20% threshold; dog/rat values are species-specific and do not override the human outcome.",
      "card_ids": ["C03","C04","C11","C21","C31"]
    },
    {
      "claim": "Epanolol, a related aryloxypropanolamine beta-blocker, had absolute oral bioavailability of 5.85 ± 2.55% with food, below the 20% threshold.",
      "card_ids": ["C17"]
    },
    {
      "claim": "Phenylephrine L1 reports poor oral bioavailability; L2 absolute estimates around 37.5–38% are above the threshold but are less transferable because phenylephrine lacks the saligenin head group and undergoes extensive presystemic metabolism.",
      "card_ids": ["C10","C29","C38","C42"]
    },
    {
      "claim": "L3 batefenterol oral exposure was negligible: all parent concentrations were non-quantifiable after a 200 µg oral dose, with pooled parent AUC0-t of 0.614 h·pgEq/mL; total radioactivity AUC was also very low. This supports low oral bioavailability for a related large lipophilic beta2 agonist, though transfer to the query is moderate.",
      "card_ids": ["C66","C56","C65"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C56","C65","C66"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself in the supplied records.",
    "No intravenous reference exposure or matched oral-versus-IV data for the query.",
    "No formulation-specific oral pharmacokinetic data for the query.",
    "Transfer from salbutamol, bambuterol, epanolol, and batefenterol is structural and pharmacological, not an exact match.",
    "Phenylephrine L2 absolute values around 38% conflict with its qualitative 'poor' L1 outcome and are less transferable due to structural differences.",
    "Most L3 oral AUC/Cmax records are for structurally unrelated molecules and do not bear directly on the query."
  ],
  "decision_summary": "The query is a saligenin beta2-agonist closely related to salbutamol and bambuterol, whose measured human oral bioavailability values are below 20%; epanolol also shows low absolute oral bioavailability. L3 adds batefenterol oral exposure showing negligible parent AUC, supporting low oral bioavailability for a related large lipophilic beta2 agonist. Other L3 records are for unrelated molecules. The physicochemical prior is absorption-unfavorable, and no active evidence supports F >= 20%. Therefore the prediction remains low."
}

